"""TunnelGuard: the engage / restore discipline around a tunnel.

The same toll discipline as the DNS guard, applied to a WireGuard
interface driven through ``wg-quick`` (TUNNEL-SPEC, "Kill-switch
semantics" — Debian/Windows):

1. Tools first. Without ``wg`` / ``wg-quick`` (the wireguard-tools
   package) nothing is attempted and the refusal names the remedy.
   Sphinx only *invokes* those GPL-2.0 programs as separate
   processes; nothing of theirs is bundled or linked (see
   debian/README.md, "VPN mode").
2. The endpoint's hostname is resolved BEFORE the tunnel engages,
   using the pre-tunnel resolver, and the answer is pinned for the
   session — the tunnel cannot resolve its own doorway from
   inside itself. A name that does not resolve refuses the engage.
3. The pre-tunnel state is saved first and verified by read-back:
   the default routes and DNS-relevant facts, and which profile.
   No verified save, no change. Intent is recorded only at a
   successful, proven engage.
4. The rendered config lives in a root-only runtime location
   (files 0600 — it holds the private key), the interface name is
   Sphinx's own, and ``wg-quick up`` brings it up.
5. Connected is PROVEN, never claimed from intent: a fresh latest
   handshake from ``wg show``, plus a routed probe where the
   platform allows (a real DNS exchange with the profile's DNS
   server, reached through the tunnel). Any failure rolls back —
   tunnel down — and keeps the record as a leftover for the user.
6. Restore is the mirror: tunnel down FIRST, then the DNS restore
   path (the caller's, the existing guard's — untouched), in the
   spec's teardown order. Keypairs are generated by invoking
   ``wg genkey`` / ``wg pubkey``; Curve25519 is never implemented
   in Python and no key is ever hardcoded.
"""
from __future__ import annotations

import ipaddress
import json
import os
import socket
import subprocess
import time
from dataclasses import dataclass, field
from enum import Enum
from pathlib import Path
from typing import Callable, List, Optional, Protocol, Tuple

from ..core.tunnel import (
    TunnelProfile,
    endpoint_host,
    parse_endpoint,
    with_endpoint_host,
)
from ..core.tunnelstore import TunnelStore, write_secret_atomically

INTERFACE_NAME = "sphinx0"
HANDSHAKE_FRESH_S = 180  # a handshake older than this is stale
MISSING_TOOLS_MESSAGE = (
    "WireGuard's tools are not installed on this machine, so "
    "Sphinx cannot open a tunnel. Install them with: "
    "sudo apt install wireguard-tools — nothing was changed."
)
OPENVPN_PHASE1_MESSAGE = (
    "This profile is an OpenVPN profile. Sphinx stores and labels "
    "OpenVPN profiles today, but connecting with one arrives in "
    "Phase 2 — in Phase 1 only WireGuard profiles connect. "
    "Nothing was changed."
)


class TunnelState(Enum):
    DISENGAGED = "disengaged"  # no record; no interface
    ENGAGED = "engaged"  # record + interface + fresh handshake
    LEFTOVER = "leftover"  # record on disk; tunnel not proven up
    UNKNOWN = "unknown"  # interface present but no record of it


@dataclass
class EngageResult:
    ok: bool
    message: str
    profile_name: str = ""


@dataclass
class RestoreResult:
    ok: bool
    message: str


@dataclass
class TunnelStatus:
    state: TunnelState
    mode: str = ""  # "vpn" or "vpn+blocker" while a record exists
    profile_name: str = ""
    handshake_age_s: Optional[int] = None
    handshake_fresh: bool = False
    intent_on: bool = False

    @property
    def connected(self) -> bool:
        """Connected is a proof, not a hope (TUNNEL-SPEC)."""
        return self.state == TunnelState.ENGAGED and self.handshake_fresh


class TunnelRunner(Protocol):
    """Everything the guard needs from the machine. Production is
    :class:`RealTunnelRunner`; tests script a fake."""

    def is_root(self) -> bool: ...
    def which(self, name: str) -> Optional[str]: ...
    def run(self, argv: List[str], input_text: Optional[str] = None) -> Tuple[int, str, str]: ...
    def resolve(self, host: str) -> List[str]: ...
    def default_routes(self) -> str: ...
    def wg_show(self, interface: str) -> Optional[str]: ...
    def interface_exists(self, interface: str) -> bool: ...
    def probe_dns(self, server: str) -> bool: ...


class RealTunnelRunner:
    """The production runner: subprocesses and sockets, nothing
    clever. ``wg`` output is parsed, never trusted blindly."""

    def is_root(self) -> bool:
        return os.geteuid() == 0

    def which(self, name: str) -> Optional[str]:
        import shutil

        return shutil.which(name)

    def run(self, argv, input_text=None):
        try:
            proc = subprocess.run(
                argv, input=input_text, capture_output=True, text=True, timeout=60
            )
        except (OSError, subprocess.TimeoutExpired) as exc:
            return 1, "", str(exc)
        return proc.returncode, proc.stdout, proc.stderr

    def resolve(self, host: str) -> List[str]:
        try:
            ipaddress.ip_address(host)
            return [host]  # already an address: nothing to resolve
        except ValueError:
            pass
        try:
            infos = socket.getaddrinfo(host, None, proto=socket.IPPROTO_UDP)
        except OSError:
            return []
        out: List[str] = []
        for info in infos:
            addr = info[4][0]
            if addr not in out:
                out.append(addr)
        return out

    def default_routes(self) -> str:
        rc, out, _ = self.run(["ip", "route", "show", "default"])
        return out.strip() if rc == 0 else ""

    def wg_show(self, interface: str) -> Optional[str]:
        rc, out, _ = self.run(["wg", "show", interface])
        return out if rc == 0 else None

    def interface_exists(self, interface: str) -> bool:
        rc, _, _ = self.run(["ip", "link", "show", interface])
        return rc == 0

    def probe_dns(self, server: str) -> bool:
        """A real DNS exchange with ``server`` (the profile's DNS,
        reached through the tunnel): a query for example.com must
        come back with a response carrying the same ID."""
        from ..core.dnswire import build_query, parse_query

        query_id = int.from_bytes(os.urandom(2), "big")
        query = build_query("example.com", query_id=query_id)
        family = socket.AF_INET6 if ":" in server else socket.AF_INET
        try:
            with socket.socket(family, socket.SOCK_DGRAM) as sock:
                sock.settimeout(4.0)
                sock.connect((server, 53))
                sock.send(query)
                data, _ = sock.recvfrom(65535)
        except OSError:
            return False
        response = parse_query(data)
        return response is not None and response.is_response and response.id == query_id


def handshake_epochs(runner: TunnelRunner, interface: str) -> List[int]:
    """Epoch seconds of each peer's latest handshake (0 = never),
    from ``wg show <iface> latest-handshakes``."""
    rc, out, _ = runner.run(["wg", "show", interface, "latest-handshakes"])
    if rc != 0:
        return []
    epochs: List[int] = []
    for line in out.splitlines():
        parts = line.split()
        if len(parts) >= 2:
            try:
                epochs.append(int(parts[1]))
            except ValueError:
                pass
    return epochs


def freshest_handshake_age(runner: TunnelRunner, interface: str, now: Optional[float] = None) -> Optional[int]:
    epochs = [e for e in handshake_epochs(runner, interface) if e > 0]
    if not epochs:
        return None
    current = time.time() if now is None else now
    return max(0, int(current - max(epochs)))


class TunnelGuard:
    def __init__(
        self,
        runner: TunnelRunner,
        store: TunnelStore,
        runtime_dir: Path,
        *,
        dns_restore: Optional[Callable[[], object]] = None,
        interface: str = INTERFACE_NAME,
    ):
        self._runner = runner
        self._store = store
        self._runtime_dir = Path(runtime_dir)
        self._dns_restore = dns_restore
        self.interface = interface

    # --- paths ------------------------------------------------------

    def _config_path(self) -> Path:
        return self._runtime_dir / "tunnel" / f"{self.interface}.conf"

    # --- status -------------------------------------------------------

    def detect_state(self) -> TunnelState:
        record = self._store.load_session()
        exists = self._runner.interface_exists(self.interface)
        if record is not None:
            if record.get("state") == "engaged" and exists:
                age = freshest_handshake_age(self._runner, self.interface)
                if age is not None and age <= HANDSHAKE_FRESH_S:
                    return TunnelState.ENGAGED
            return TunnelState.LEFTOVER
        return TunnelState.UNKNOWN if exists else TunnelState.DISENGAGED

    def status(self) -> TunnelStatus:
        record = self._store.load_session() or {}
        state = self.detect_state()
        age = None
        fresh = False
        if self._runner.interface_exists(self.interface):
            age = freshest_handshake_age(self._runner, self.interface)
            fresh = age is not None and age <= HANDSHAKE_FRESH_S
        return TunnelStatus(
            state=state,
            mode=str(record.get("mode", "")),
            profile_name=str(record.get("profile", "")),
            handshake_age_s=age,
            handshake_fresh=fresh,
            intent_on=bool(record.get("intent")),
        )

    # --- keypairs ------------------------------------------------------

    def generate_keypair(self) -> Tuple[str, str]:
        """(private, public) from `wg genkey` / `wg pubkey` — the
        vetted tool, invoked; never Python Curve25519, never a
        hardcoded or derived key."""
        if self._runner.which("wg") is None:
            raise RuntimeError(MISSING_TOOLS_MESSAGE)
        rc, private, err = self._runner.run(["wg", "genkey"])
        private = private.strip()
        if rc != 0 or not private:
            raise RuntimeError(f"wg genkey failed: {err.strip() or 'no key produced'}")
        rc, public, err = self._runner.run(["wg", "pubkey"], input_text=private + "\n")
        public = public.strip()
        if rc != 0 or not public:
            raise RuntimeError(f"wg pubkey failed: {err.strip() or 'no key produced'}")
        return private, public

    # --- engage ----------------------------------------------------------

    def engage(self, profile: TunnelProfile, mode: str = "vpn+blocker") -> EngageResult:
        name = profile.name or ""
        if profile.protocol == "openvpn":
            return EngageResult(False, OPENVPN_PHASE1_MESSAGE, name)
        if profile.protocol != "wireguard":
            return EngageResult(
                False,
                f"This profile's protocol ('{profile.protocol}') is not "
                "one Sphinx implements — it is stored and labeled, and "
                "refused here rather than half-connected. Nothing was changed.",
                name,
            )
        if not self._runner.is_root():
            return EngageResult(
                False,
                "Opening a tunnel changes this machine's routes, so it "
                "needs root. Run it with sudo — nothing was changed.",
                name,
            )
        if self._runner.which("wg") is None or self._runner.which("wg-quick") is None:
            return EngageResult(False, MISSING_TOOLS_MESSAGE, name)

        # One tunnel at a time: a second connect goes through the
        # ordinary stop path for the first (TUNNEL-SPEC).
        current = self._store.load_session()
        if current is not None and current.get("state") == "engaged":
            stopped = self.disengage()
            if not stopped.ok:
                return EngageResult(
                    False,
                    "Another tunnel is up and Sphinx could not bring it "
                    f"down cleanly first: {stopped.message} Nothing else "
                    "was changed.",
                    name,
                )

        # Resolve BEFORE engaging, with the pre-tunnel resolver,
        # and pin the answer for the session.
        host = endpoint_host(profile.endpoint)
        try:
            ipaddress.ip_address(host)
            pinned_host = host
        except ValueError:
            answers = self._runner.resolve(host)
            if not answers:
                return EngageResult(
                    False,
                    f"The server name '{host}' could not be resolved "
                    "before connecting, so the tunnel was not opened — "
                    "a tunnel cannot look up its own doorway from "
                    "inside itself. Check the name and your connection, "
                    "then try again. Nothing was changed.",
                    name,
                )
            pinned_host = answers[0]
        pinned_endpoint = with_endpoint_host(profile.endpoint, pinned_host)

        # Save the pre-tunnel state first, verified by read-back.
        record = {
            "version": 1,
            "state": "engaged",
            "mode": mode,
            "profile": name,
            "interface": self.interface,
            "endpoint": profile.endpoint,
            "pinned_endpoint": pinned_endpoint,
            "intent": False,  # intent is written only at a PROVEN engage
            "engaged_at_ms": int(time.time() * 1000),
            "pre_tunnel": {
                "default_routes": self._runner.default_routes(),
                "dns_record_present": (
                    self._store.state_dir / "dns-backup.json"
                ).is_file(),
            },
        }
        try:
            self._store.save_session(record)
        except OSError as exc:
            return EngageResult(
                False,
                f"Sphinx could not save the pre-tunnel state ({exc}), "
                "so it changed nothing.",
                name,
            )
        if self._store.load_session() != record:
            return EngageResult(
                False,
                "Sphinx could not verify the saved pre-tunnel state by "
                "reading it back, so it changed nothing.",
                name,
            )

        # Render the session config (endpoint pinned) into the
        # root-only runtime location, then bring the tunnel up.
        rendered = self._render_config(profile, pinned_endpoint)
        config_path = self._config_path()
        try:
            write_secret_atomically(config_path, rendered.encode("utf-8"))
        except OSError as exc:
            self._mark_leftover(record, f"could not write the tunnel config: {exc}")
            return EngageResult(False, f"The tunnel config could not be written ({exc}); nothing was connected.", name)
        rc, _out, err = self._runner.run(["wg-quick", "up", str(config_path)])
        if rc != 0:
            self._rollback_up(record, config_path)
            return EngageResult(
                False,
                f"wg-quick could not bring the tunnel up ({err.strip() or 'no reason given'}). "
                "The attempt was rolled back and the record kept — "
                "'sphinx vpn status' shows the state.",
                name,
            )

        # Prove it: a routed probe first (which also prompts the
        # first handshake), then handshake freshness from wg show.
        probe_ok = True
        if profile.dns:
            probe_ok = self._runner.probe_dns(profile.dns[0])
        age = freshest_handshake_age(self._runner, self.interface)
        if age is None or age > HANDSHAKE_FRESH_S or not probe_ok:
            self._rollback_up(record, config_path)
            why = (
                "no completed handshake was reported by wg"
                if age is None
                else "the handshake is stale"
                if age > HANDSHAKE_FRESH_S
                else "the routed probe through the tunnel did not answer"
            )
            return EngageResult(
                False,
                f"The tunnel came up but did not prove it is carrying "
                f"traffic ({why}) — the server's identity may not match "
                "this profile, or the server may be unreachable. The "
                "tunnel was brought back down and the record kept; "
                "Sphinx never claims 'connected' without that proof.",
                name,
            )

        record["intent"] = True
        record["handshake_age_s"] = age
        try:
            self._store.save_session(record)
        except OSError:
            pass  # the tunnel IS proven; intent bookkeeping follows
        scope = "all of this machine's traffic" if profile.scope == "all" else "some of this machine's traffic (a split tunnel)"
        return EngageResult(
            True,
            f"VPN on — '{name}' is connected and proven (handshake "
            f"{age}s ago). {scope.capitalize()} goes through the "
            "server you chose.",
            name,
        )

    def _render_config(self, profile: TunnelProfile, pinned_endpoint: str) -> str:
        """The session's wg-quick config: the profile's own text
        with the endpoint pinned to the pre-resolved address, and
        the interface renamed by wg-quick's file-name rule (the
        file IS sphinx0.conf, so the interface is sphinx0).

        The profile's DNS line is NOT passed to wg-quick: Sphinx
        manages DNS itself (the resolver guard for the system
        path, the daemon's upstream choice in VPN+Blocker), and
        wg-quick would hand the line to resolvconf — a second,
        unrecorded DNS change Sphinx could not restore exactly.
        The profile record keeps the DNS servers; only this
        session's rendered copy omits the line."""
        lines = []
        for line in profile.export_text().splitlines():
            key, sep, _ = line.partition("=")
            if sep and key.strip().lower() == "dns":
                continue
            lines.append(line)
        text = "\n".join(lines) + "\n"
        host = endpoint_host(profile.endpoint)
        if host != pinned_endpoint:
            text = text.replace(
                f"Endpoint = {profile.endpoint}",
                f"Endpoint = {pinned_endpoint}",
            )
        return text

    def _rollback_up(self, record: dict, config_path: Path) -> None:
        try:
            self._runner.run(["wg-quick", "down", str(config_path)])
        except Exception:
            pass
        self._mark_leftover(record, "engage did not prove; rolled back")

    def _mark_leftover(self, record: dict, note: str) -> None:
        record = dict(record)
        record["state"] = "leftover"
        record["intent"] = False
        record["note"] = note
        try:
            self._store.save_session(record)
        except OSError:
            pass

    # --- disengage ---------------------------------------------------------

    def disengage(self) -> RestoreResult:
        """Tunnel down first, then the DNS restore path (the
        existing guard's, untouched) when a DNS record requires it
        — TUNNEL-SPEC's teardown order."""
        if not self._runner.is_root():
            return RestoreResult(
                False,
                "Closing a tunnel changes this machine's routes, so "
                "it needs root. Run it with sudo — nothing was changed.",
            )
        record = self._store.load_session()
        if record is None and not self._runner.interface_exists(self.interface):
            return RestoreResult(True, "No VPN tunnel is up.")
        config_path = self._config_path()
        if self._runner.interface_exists(self.interface):
            if self._runner.which("wg-quick") is None:
                return RestoreResult(False, MISSING_TOOLS_MESSAGE)
            rc, _out, err = self._runner.run(["wg-quick", "down", str(config_path)])
            if rc != 0 and self._runner.interface_exists(self.interface):
                return RestoreResult(
                    False,
                    f"wg-quick could not bring the tunnel down "
                    f"({err.strip() or 'no reason given'}). The tunnel "
                    "record was kept and DNS was not touched — the "
                    "teardown order is tunnel first, then DNS.",
                )
        # Tunnel is down (or never was): now the DNS restore path.
        if self._dns_restore is not None:
            result = self._dns_restore()
            ok = getattr(result, "ok", True)
            if not ok:
                self._mark_leftover(record or {}, "tunnel down; DNS restore did not verify")
                return RestoreResult(
                    False,
                    "The tunnel is down, but restoring DNS did not "
                    f"verify: {getattr(result, 'message', '')} The "
                    "records were kept — 'sphinx status' shows the "
                    "state.",
                )
        self._store.clear_session()
        try:
            config_path.unlink(missing_ok=True)
        except OSError:
            pass
        name = (record or {}).get("profile", "")
        return RestoreResult(
            True,
            f"VPN off{f' — {name} disconnected' if name else ''}. "
            "Your DNS settings are as they were before the tunnel.",
        )

    def teardown_for_removal(self) -> RestoreResult:
        """prerm's path: a live tunnel comes down before removal;
        when it cannot come down, the removal must stop loudly
        (the caller — packaging/prerm — exits 1 on this result)."""
        record = self._store.load_session()
        if record is None and not self._runner.interface_exists(self.interface):
            return RestoreResult(True, "No VPN tunnel is up.")
        return self.disengage()
